args.script:
// Create placeholder SpriteRenderer for Adrenaline item icon
var placeholderPath = "Assets/TJGenerators/History/Sprite_20260810_234333.png";

// Load the placeholder sprite
var sprite = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>(placeholderPath);
if (sprite == null)
{
    // Force reimport to ensure it's imported as a Sprite
    UnityEditor.AssetDatabase.ImportAsset(placeholderPath, UnityEditor.ImportAssetOptions.ForceUpdate);
    sprite = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>(placeholderPath);
}
if (sprite == null)
{
    UnityEngine.Debug.LogError($"Failed to load sprite at {placeholderPath}");
    return;
}

// Load Sprite-Lit-Default material for URP 2D lighting
var mat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Materials/SpriteLit.mat");
if (mat == null)
{
    UnityEngine.Debug.LogWarning("SpriteLit.mat not found, falling back to default material.");
}

// Create new empty GameObject (never reuse existing Cube/Plane/Quad)
var go = new UnityEngine.GameObject("AdrenalineItemSprite");

// Add SpriteRenderer and configure
var sr = go.AddComponent<UnityEngine.SpriteRenderer>();
sr.sprite = sprite;
if (mat != null)
    sr.sharedMaterial = mat;

// Set localScale for item icon (~2 units wide at 2048px / PPU=100)
go.transform.localScale = UnityEngine.Vector3.one * 0.10f;

// Position in scene at origin
go.transform.position = new UnityEngine.Vector3(0, 0, 0);

// Mark scene dirty and save
var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);

UnityEngine.Debug.Log($"[AdrenalineSprite] Created placeholder GameObject '{go.name}' with sprite '{sprite.name}', scale={go.transform.localScale}, material={(sr.sharedMaterial != null ? sr.sharedMaterial.name : "null")}");

